from pathlib import Path
import tempfile, subprocess, json, re
root=Path.cwd()
test = r'''
<script>
(() => {
  const out=[];const check=(n,o,e='')=>out.push((o?'PASS':'FAIL')+' '+n+(e?' ('+e+')':''));
  const inside=(el,n)=>{const r=el.getBoundingClientRect();check(n,r.left>=-0.5&&r.top>=-0.5&&r.right<=innerWidth+0.5&&r.bottom<=innerHeight+0.5,`${Math.round(r.left)},${Math.round(r.top)} ${Math.round(r.right)}x${Math.round(r.bottom)} vp ${innerWidth}x${innerHeight}`)};
  try{
    check('menu background image set',getComputedStyle(document.querySelector('#menu .scene')).backgroundImage.includes('menu-bg.jpg'));
    check('scenario not active',!document.getElementById('scenario').classList.contains('active'));
    document.getElementById('newGame').click();
    check('scenario active',document.getElementById('scenario').classList.contains('active'));
    check('scenario next disabled initially',document.getElementById('scenarioNext').disabled);
    document.getElementById('beginningScenario').click();
    check('scenario next enabled',!document.getElementById('scenarioNext').disabled);
    check('character screen still hidden',!document.getElementById('characterSelect').classList.contains('active'));
    document.getElementById('scenarioNext').click();
    check('character screen opens',document.getElementById('characterSelect').classList.contains('active'));
    check('scenario hidden',!document.getElementById('scenario').classList.contains('active'));
    const img=document.querySelector('.portrait-frame img');
    check('portrait loads',img.complete&&img.naturalWidth===683&&img.naturalHeight===1024,img.naturalWidth+'x'+img.naturalHeight);
    check('name shown',document.querySelector('.character-name').textContent.trim()==='Lux Osborn');
    check('bio complete',document.querySelector('.character-biography').textContent.includes('responsibility that must be earned'));
    inside(document.querySelector('.scenario-frame'),'character frame');
    inside(img,'portrait frame');
    inside(document.getElementById('characterNext'),'character next');
    const bio=document.querySelector('.character-biography');bio.scrollTop=99999;
    check('biography scrollable',bio.scrollHeight>bio.clientHeight&&bio.scrollTop>0,bio.scrollTop+'/'+(bio.scrollHeight-bio.clientHeight));
    document.getElementById('characterNext').click();
    check('game starts',document.getElementById('game').classList.contains('active'));
    inside(document.querySelector('.map-board'),'map board');
    const t=document.querySelector('.territory[data-id="1"]');t.dispatchEvent(new MouseEvent('click',{bubbles:true}));
    document.getElementById('march').click();
    check('conquest works',document.getElementById('realmStat').textContent.trim()==='2 / 5');
    document.getElementById('saveReturn').click();
    check('load enabled',!document.getElementById('loadGame').disabled);
    document.getElementById('newGame').click();
    document.getElementById('beginningScenario').click();
    document.getElementById('scenarioNext').click();
    document.getElementById('characterBack').click();
    check('character back to scenario',document.getElementById('scenario').classList.contains('active'));
    document.getElementById('scenarioNext').click();
    check('selection kept when going back',document.getElementById('characterSelect').classList.contains('active'));
    const fails=out.filter(x=>x.startsWith('FAIL'));
    document.body.dataset.result=JSON.stringify({size:innerWidth+'x'+innerHeight,pass:out.length-fails.length,fail:fails.length,details:out});
  }catch(e){document.body.dataset.result=JSON.stringify({error:e.message+' | '+e.stack})}
})();
</script>'''
sizes=[(500,900),(800,360),(1280,800)]
